// Take the first queued item
const items = $input.all();
const first = items[0]?.json || {};

return {
  json: {
    id: first.id,
    pillar: first.pillar,
    hook: first.hook,
    format: first.format,
    icp: first.icp || 'SaaS founders and marketers'
  }
};

